-- One photo row per piece. A storage_path beginning with "/" is a file the
-- site serves itself, so this needs no upload into Supabase Storage.
insert into product_images (product_id, storage_path, alt_th, sort_order)
select p.id, '/test-photo.jpg', p.name || ' ' || p.sku, 0
from products p
where p.description = 'ชิ้นตัวอย่างสำหรับทดสอบระบบ ยังไม่ใช่สินค้าจริงของร้าน'
  and not exists (select 1 from product_images pi where pi.product_id = p.id);

commit;

